<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('security.view');if(is_post()){require_permission('security.manage');verify_csrf();$id=filter_var(input('id'),FILTER_VALIDATE_INT);$status=strtoupper((string)input('status'));if(!$id||!in_array($status,['ACTIVE','BLOCKED','REPLACEMENT_PENDING'],true)){flash('error','Invalid device update.');}else{$pdo=db();$pdo->beginTransaction();try{$stmt=$pdo->prepare('SELECT * FROM user_devices WHERE id=? FOR UPDATE');$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new RuntimeException('Device not found.');$pdo->prepare('UPDATE user_devices SET status=?,updated_at=NOW() WHERE id=?')->execute([$status,$id]);if($status==='BLOCKED')$pdo->prepare('UPDATE user_sessions SET revoked_at=NOW() WHERE user_id=? AND device_id=? AND revoked_at IS NULL')->execute([$old['user_id'],$old['device_id']]);log_security((int)$old['user_id'],'DEVICE_STATUS_CHANGED',$status==='BLOCKED'?'HIGH':'MEDIUM','Administrator changed device status',['device_id'=>$old['device_id'],'status'=>$status]);audit_log((int)admin()['id'],'DEVICE_STATUS_CHANGED','devices',(string)$id,['status'=>$old['status']],['status'=>$status]);$pdo->commit();flash('success','Device status updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Could not update device.':$e->getMessage());}}redirect('/admin/fraud/devices.php');}$q=trim((string)input('q'));$where=$q!==''?' WHERE u.name LIKE ? OR d.device_id LIKE ?':'';$stmt=db()->prepare('SELECT d.*,u.name,u.mobile FROM user_devices d JOIN users u ON u.id=d.user_id'.$where.' ORDER BY d.id DESC LIMIT 250');$stmt->execute($where?['%'.$q.'%','%'.$q.'%']:[]);$rows=$stmt->fetchAll();$pageTitle='User devices';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Registered devices</h2><a href="<?=e(app_url('/admin/fraud/login-attempts.php'))?>">Login attempts →</a></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="User or device ID"><button class="btn">Search</button></form><div class="table-wrap"><table><thead><tr><th>User</th><th>Device</th><th>Platform</th><th>IP</th><th>Status</th><th>Last active</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="<?=e(app_url('/admin/users/view.php?id='.$r['user_id']))?>"><?=e($r['name'])?></a></td><td><?=e($r['device_name']??'—')?><br><small><?=e($r['device_id'])?></small></td><td><?=e(($r['platform']??'—').' '.($r['os_version']??''))?></td><td><?=e($r['ip_address']??'—')?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['last_active_at']??'—')?></td><td><?php if(can('security.manage')):?><form method="post" class="actions" data-confirm="Change this device status and revoke its sessions if blocked?"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="status"><?php foreach(['ACTIVE','BLOCKED','REPLACEMENT_PENDING'] as $s):?><option <?=$s===$r['status']?'selected':''?>><?=$s?></option><?php endforeach?></select><button class="btn small">Save</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';

